import zipfile
import xml.etree.ElementTree as ET

NS = {'m': 'http://schemas.openxmlformats.org/spreadsheetml/2006/main',
      'r': 'http://schemas.openxmlformats.org/officeDocument/2006/relationships'}

path = 'budget.xlsx'
with zipfile.ZipFile(path) as z:
    names = z.namelist()
    print("Files in archive:")
    for n in names:
        print("  ", n)

    # workbook.xml -> sheet names and rIds
    wb = ET.fromstring(z.read('xl/workbook.xml'))
    rels = ET.fromstring(z.read('xl/_rels/workbook.xml.rels'))
    rel_map = {}
    for rel in rels:
        rel_map[rel.get('Id')] = rel.get('Target')

    # shared strings
    shared = []
    if 'xl/sharedStrings.xml' in names:
        ss = ET.fromstring(z.read('xl/sharedStrings.xml'))
        for si in ss.findall('m:si', NS):
            text = ''.join(t.text or '' for t in si.iter('{http://schemas.openxmlformats.org/spreadsheetml/2006/main}t'))
            shared.append(text)

    def col_to_idx(ref):
        letters = ''.join(c for c in ref if c.isalpha())
        idx = 0
        for ch in letters:
            idx = idx * 26 + (ord(ch.upper()) - 64)
        return idx - 1

    print("\nShared strings count:", len(shared))

    for sheet in wb.find('m:sheets', NS):
        name = sheet.get('name')
        rid = sheet.get('{http://schemas.openxmlformats.org/officeDocument/2006/relationships}id')
        target = rel_map.get(rid, '')
        sheet_path = 'xl/' + target if not target.startswith('/') else target.lstrip('/')
        print(f"\n--- Sheet: {name} ({sheet_path}) ---")
        ws = ET.fromstring(z.read(sheet_path))
        data = ws.find('m:sheetData', NS)
        for row in data.findall('m:row', NS):
            vals = {}
            for c in row.findall('m:c', NS):
                ref = c.get('r')
                t = c.get('t')
                v = c.find('m:v', NS)
                isel = c.find('m:is', NS)
                if v is not None:
                    val = v.text
                elif isel is not None:
                    val = ''.join(x.text or '' for x in isel.iter('{http://schemas.openxmlformats.org/spreadsheetml/2006/main}t'))
                else:
                    val = ''
                if t == 's':
                    try:
                        val = shared[int(val)]
                    except (ValueError, IndexError):
                        val = f"<shared#{val}>"
                vals[ref] = val
            if vals:
                maxcol = max(col_to_idx(r) for r in vals)
                cells = [''] * (maxcol + 1)
                for ref, val in vals.items():
                    cells[col_to_idx(ref)] = val
                print(' | '.join(repr(x) for x in cells))

import zipfile
import xml.etree.ElementTree as ET

M = '{http://schemas.openxmlformats.org/spreadsheetml/2006/main}'

def inline_text(c):
    isel = c.find(M + 'is')
    if isel is not None:
        return ''.join(t.text or '' for t in isel.iter(M + 't'))
    return ''

def cell_val(c):
    v = c.find(M + 'v')
    if v is not None:
        try:
            return float(v.text)
        except (TypeError, ValueError):
            return v.text
    return None

with zipfile.ZipFile('budget.xlsx') as z:
    ws = ET.fromstring(z.read('xl/worksheets/sheet1.xml'))
    data = ws.find(M + 'sheetData')

    rows = {}
    for row in data.findall(M + 'row'):
        r = int(row.get('r'))
        cells = {}
        for c in row.findall(M + 'c'):
            ref = c.get('r')
            if c.get('t') == 'inlineStr':
                cells[ref] = inline_text(c)
            else:
                cells[ref] = cell_val(c)
        rows[r] = cells

    # Expense rows: rows 11-22, col A=category, col B=item, col C=amount
    totals = {}
    items = []
    for r in range(11, 23):
        cat = rows[r].get(f'A{r}')
        item = rows[r].get(f'B{r}')
        amt = rows[r].get(f'C{r}')
        items.append((cat, item, amt))
        totals[cat] = totals.get(cat, 0) + amt

    grand = sum(totals.values())
    print("Category totals:")
    for cat, t in totals.items():
        print(f"  {cat}: {t:,.2f}")
    print(f"TOTAL EXPENSES: {grand:,.2f}")

    # Verify against the workbook's own formula range
    file_total = sum(rows[r].get(f'C{r}', 0) for r in range(11, 23))
    print("Sum of C11:C22 (matches file formula):", file_total)

